import{_ as a,b as i,e as t,a8 as o}from"./chunks/framework.CNHV3T2x.js";const p=JSON.parse('{"title":"Overview","description":"","frontmatter":{"date":1787774264000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"guide/using-timage32/overview.md","filePath":"guide/using-timage32/overview.md","lastUpdated":1787774264000,"timestamp":1787774264000,"datetime":"2026-08-26T19:57:44.000Z","contributors":[{"commits":1,"email":"anders@melander.dk","name":"Anders Melander","avatar":"https://gravatar.com/avatar/a6bff52a3ccbe999ab6406528ffe48f1","maintainer":false,"links":[]}]}'),s={name:"guide/using-timage32/overview.md"};function n(r,e,c,l,d,h){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This section describes the behavior and properties of the <a href="/api/GR32_Image/TCustomImage32">TCustomImage32</a> base class and its derived class, the <a href="/api/GR32_Image/TImage32">TImage32</a> control, as well as their realization of layers.</p><p>Since <code>TCustomImage32</code> and <code>TImage32</code> share the same behavior, we will denote both of them here as <code>TImage32</code>. Most of the description applies to the <code>TImgView32</code> control as well.</p></div><p>TImage32 is an image displaying visual control, which also holds a collection of layers.</p><p>The internal image of the control is a <code>TBitmap32</code> object. The scale and position of the image within the control’s boundaries can be controlled with several properties. See <a href="./bitmap-image">Bitmap Image</a> for details.</p><p><code>TImage32</code> maintains a collection of layers. A layer is, generally speaking, an entity which ‘knows’ how to combine itself with the back buffer of the control. See ‘<a href="./using-layers">Using Layers</a>‘ for details.</p><p>When the image paints itself, it runs through several <a href="./paint-stages">Paint Stages</a> which determine the order in which layers and the bitmap image are painted. This order is completely customizeable.</p><p>To avoid flicker and to speed-up scaling and blending operations, each layer and the bitmap image is painted to a back-buffer of the control. See the description of <a href="./repaint-optimization">Repaint Optimization</a> for details on this.</p><p>Finally, <code>TImage32</code> supports change notification via the <a href="/api/GR32_Image/TCustomImage32/Events/OnChange">OnChange</a> event, which is done similar to change notification in <code>TBitmap32</code>. Basically, it redirects change notification from its layers and the bitmap image.</p>',8)])])}const g=a(s,[["render",n]]);export{p as __pageData,g as default};
